content:
:root {
  --bg-color: #1a1a2e;
  --panel-bg: #16213e;
  --accent-color: #0f3460;
  --primary-color: #e94560;
  --text-color: #ffffff;
  --snake-color: #4ecc6d;
  --food-color: #ffcc00;
  --grid-size: 400px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  font-family: 'Courier New', Courier, monospace;
}

body {
  background-color: var(--bg-color);
  color: var(--text-color);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  overflow-y: auto;
  user-select: none;
  padding: 10px;
}

.app-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background-color: var(--panel-bg);
  border: 4px solid var(--accent-color);
  border-radius: 12px;
  padding: 20px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5);
  max-width: 480px;
  width: 100%;
}

.game-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  margin-bottom: 15px;
  width: 100%;
}

.game-header h1 {
  font-size: 1.8rem;
  color: var(--primary-color);
  margin-bottom: 10px;
  text-shadow: 2px 2px #000;
  letter-spacing: 2px;
}

.score-board {
  display: flex;
  justify-content: space-around;
  width: 100%;
  font-size: 1.1rem;
  background-color: var(--bg-color);
  padding: 8px 16px;
  border-radius: 6px;
  border: 2px dashed var(--accent-color);
}

.game-board {
  position: relative;
  width: var(--grid-size);
  height: var(--grid-size);
  max-width: 85vw;
  max-height: 85vw;
  background-color: #0d1117;
  border: 3px solid var(--accent-color);
  border-radius: 4px;
  overflow: hidden;
}

.snake-segment {
  position: absolute;
  background-color: var(--snake-color);
  border-radius: 2px;
  border: 1px solid #0d1117;
}

.food {
  position: absolute;
  background-color: var(--food-color);
  border-radius: 50%;
  box-shadow: 0 0 8px var(--food-color);
}

.controls-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  margin-top: 20px;
  width: 100%;
}

.d-pad {
  display: grid;
  grid-template-columns: repeat(3, 60px);
  grid-template-rows: repeat(2, 60px);
  gap: 8px;
  justify-content: center;
  margin-bottom: 15px;
}

.d-btn {
  background-color: var(--accent-color);
  color: var(--text-color);
  border: 2px solid var(--primary-color);
  border-radius: 8px;
  font-size: 1.5rem;
  font-weight: bold;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 4px 0 #091933;
  transition: transform 0.1s, box-shadow 0.1s, filter 0.2s;
}

.d-btn:hover {
  filter: brightness(1.2);
}

.d-btn:focus-visible,
.btn:focus-visible {
  outline: 3px solid var(--text-color);
  outline-offset: 2px;
}

.d-btn:active {
  transform: translateY(4px);
  box-shadow: 0 0 0 #091933;
}

/* 十字キーの配置調整 */
.d-btn:nth-child(1) { grid-column: 2; grid-row: 1; } /* UP */
.d-btn:nth-child(2) { grid-column: 1; grid-row: 2; } /* LEFT */
.d-btn:nth-child(3) { grid-column: 3; grid-row: 2; } /* RIGHT */
.d-btn:nth-child(4) { grid-column: 2; grid-row: 2; } /* DOWN */

.btn {
  background-color: var(--primary-color);
  color: var(--text-color);
  border: none;
  border-radius: 6px;
  padding: 10px 20px;
  font-size: 1.1rem;
  font-weight: bold;
  cursor: pointer;
  box-shadow: 0 4px 0 #902a3c;
  transition: transform 0.1s, box-shadow 0.1s, filter 0.2s;
  letter-spacing: 1px;
}

.btn:hover {
  filter: brightness(1.15);
}

.btn:active {
  transform: translateY(4px);
  box-shadow: 0 0 0 #902a3c;
}

.overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.8);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 10;
}

.modal {
  background-color: var(--panel-bg);
  border: 3px solid var(--primary-color);
  border-radius: 10px;
  padding: 30px;
  text-align: center;
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.8);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 15px;
  max-width: 80%;
}

.modal h2 {
  font-size: 1.5rem;
  color: var(--primary-color);
}

.modal p {
  font-size: 1.1rem;
}

@media (max-width: 480px) {
  .app-container {
    padding: 12px;
    border-width: 2px;
  }
  .game-header h1 {
    font-size: 1.4rem;
  }
  .score-board {
    font-size: 0.95rem;
    padding: 6px 10px;
  }
  .d-pad {
    grid-template-columns: repeat(3, 50px);
    grid-template-rows: repeat(2, 50px);
    gap: 6px;
  }
  .d-btn {
    font-size: 1.2rem;
  }
  .modal {
    padding: 20px;
  }
}

export type Direction = 'UP' | 'DOWN' | 'LEFT' | 'RIGHT';

export interface Point {
  x: number;
  y: number;
}

export type GameState = 'START' | 'PLAYING' | 'GAME_OVER';

export type Difficulty = 'EASY' | 'NORMAL' | 'HARD';

export interface GameSettings {
  difficulty: Difficulty;
  soundEnabled: boolean;
  gridSize: number;
  gameSpeed: number;
}

export interface ScoreState {
  score: number;
  highScore: number;
}

import React from 'react';
import { Point } from '../types';
import '../index.css';

interface GameBoardProps {
  snake: Point[];
  food: Point;
  gridSize: number;
}

const SnakeSegment = React.memo(({ segment, gridSize }: { segment: Point; gridSize: number }) => {
  const style = {
    left: `${(segment.x / gridSize) * 100}%`,
    top: `${(segment.y / gridSize) * 100}%`,
    width: `${100 / gridSize}%`,
    height: `${100 / gridSize}%`,
  };
  return <div className="snake-segment" style={style} />;
});

SnakeSegment.displayName = 'SnakeSegment';

export default function GameBoard({ snake = [], food = { x: 0, y: 0 }, gridSize = 20 }: GameBoardProps) {
  return (
    <div className="game-board">
      {snake.map((segment, index) => (
        <SnakeSegment key={index} segment={segment} gridSize={gridSize} />
      ))}
      <div
        className="food"
        style={{
          left: `${(food.x / gridSize) * 100}%`,
          top: `${(food.y / gridSize) * 100}%`,
          width: `${100 / gridSize}%`,
          height: `${100 / gridSize}%`,
        }}
      />
    </div>
  );
}

import React from 'react';
import { Direction, GameState } from '../types';
import '../index.css';

interface ControlsProps {
  onDirectionChange: (dir: Direction) => void;
  onRestart: () => void;
  gameState: GameState;
  onStart: () => void;
}

export default function Controls({
  onDirectionChange,
  onRestart,
  gameState,
  onStart,
}: ControlsProps) {
  const handleTouchStart = (e: React.TouchEvent, callback: () => void) => {
    e.preventDefault();
    callback();
  };

  return (
    <div className="controls-container">
      <div className="d-pad">
        <button 
          className="d-btn" 
          aria-label="上に移動"
          onClick={() => onDirectionChange('UP')}
          onTouchStart={(e) => handleTouchStart(e, () => onDirectionChange('UP'))}
        >
          ▲
        </button>
        <button 
          className="d-btn" 
          aria-label="左に移動"
          onClick={() => onDirectionChange('LEFT')}
          onTouchStart={(e) => handleTouchStart(e, () => onDirectionChange('LEFT'))}
        >
          ◀
        </button>
        <button 
          className="d-btn" 
          aria-label="右に移動"
          onClick={() => onDirectionChange('RIGHT')}
          onTouchStart={(e) => handleTouchStart(e, () => onDirectionChange('RIGHT'))}
        >
          ▶
        </button>
        <button 
          className="d-btn" 
          aria-label="下に移動"
          onClick={() => onDirectionChange('DOWN')}
          onTouchStart={(e) => handleTouchStart(e, () => onDirectionChange('DOWN'))}
        >
          ▼
        </button>
      </div>

      {gameState === 'START' && (
        <button className="btn" onClick={() => onStart?.()}>
          ゲームスタート
        </button>
      )}
      {gameState === 'GAME_OVER' && (
        <button className="btn" onClick={() => onRestart?.()}>
          もう一度プレイ
        </button>
      )}
    </div>
  );
}

import { useState, useEffect, useCallback, useRef } from 'react';
import { Direction, Point, GameState } from './types';
import GameBoard from './components/GameBoard';
import Controls from './components/Controls';
import './index.css';

const GRID_SIZE = 20; // 20x20 grid
const INITIAL_SNAKE: Point[] = [
  { x: 10, y: 10 },
  { x: 10, y: 11 },
  { x: 10, y: 12 },
];
const INITIAL_DIRECTION: Direction = 'UP';
const BASE_GAME_SPEED = 120; // ms

export default function App() {
  const [gameState, setGameState] = useState<GameState>('START');
  const [isPaused, setIsPaused] = useState<boolean>(false);
  const [snake, setSnake] = useState<Point[]>(INITIAL_SNAKE);
  const [food, setFood] = useState<Point>({ x: 5, y: 5 });
  const [direction, setDirection] = useState<Direction>(INITIAL_DIRECTION);
  const [score, setScore] = useState<number>(0);
  const [highScore, setHighScore] = useState<number>(() => {
    const saved = localStorage.getItem('snake_highscore');
    return saved ? parseInt(saved, 10) : 0;
  });

  const directionRef = useRef<Direction>(direction);
  directionRef.current = direction;

  // スコアに応じてゲームスピードを動的に変化（難易度上昇）
  const gameSpeed = Math.max(50, BASE_GAME_SPEED - Math.floor(score / 50) * 10);

  const generateFood = useCallback((currentSnake: Point[]): Point => {
    let newFood: Point;
    while (true) {
      newFood = {
        x: Math.floor(Math.random() * GRID_SIZE),
        y: Math.floor(Math.random() * GRID_SIZE),
      };
      // Check if food is on snake
      const collision = currentSnake.some(
        (segment) => segment.x === newFood.x && segment.y === newFood.y
      );
      if (!collision) break;
    }
    return newFood;
  }, []);

  const startGame = () => {
    const newSnake = INITIAL_SNAKE;
    setSnake(newSnake);
    setFood(generateFood(newSnake));
    setDirection(INITIAL_DIRECTION);
    directionRef.current = INITIAL_DIRECTION;
    setScore(0);
    setIsPaused(false);
    setGameState('PLAYING');
  };

  const togglePause = () => {
    if (gameState === 'PLAYING') {
      setIsPaused((prev) => !prev);
    }
  };

  const handleDirectionChange = useCallback((newDir: Direction) => {
    if (isPaused) return;
    const current = directionRef.current;
    if (
      (newDir === 'UP' && current === 'DOWN') ||
      (newDir === 'DOWN' && current === 'UP') ||
      (newDir === 'LEFT' && current === 'RIGHT') ||
      (newDir === 'RIGHT' && current === 'LEFT')
    ) {
      return;
    }
    setDirection(newDir);
  }, [isPaused]);

  // Keyboard controls & Pause toggle
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === ' ' || e.code === 'Space') {
        if (gameState === 'PLAYING') {
          e.preventDefault();
          togglePause();
        }
        return;
      }

      if (gameState !== 'PLAYING' || isPaused) return;
      switch (e.key) {
        case 'ArrowUp':
        case 'w':
        case 'W':
          handleDirectionChange('UP');
          break;
        case 'ArrowDown':
        case 's':
        case 'S':
          handleDirectionChange('DOWN');
          break;
        case 'ArrowLeft':
        case 'a':
        case 'A':
          handleDirectionChange('LEFT');
          break;
        case 'ArrowRight':
        case 'd':
        case 'D':
          handleDirectionChange('RIGHT');
          break;
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [gameState, isPaused, handleDirectionChange]);

  // 1フレーム分のスネーク移動・衝突判定ロジック（保守性向上のため分離）
  const moveSnake = useCallback(() => {
    setSnake((prevSnake) => {
      const head = { ...prevSnake[0] };

      switch (directionRef.current) {
        case 'UP':
          head.y -= 1;
          break;
        case 'DOWN':
          head.y += 1;
          break;
        case 'LEFT':
          head.x -= 1;
          break;
        case 'RIGHT':
          head.x += 1;
          break;
      }

      // Wall collision
      if (
        head.x < 0 ||
        head.x >= GRID_SIZE ||
        head.y < 0 ||
        head.y >= GRID_SIZE
      ) {
        setGameState('GAME_OVER');
        return prevSnake;
      }

      // Self collision
      if (prevSnake.slice(1).some((segment) => segment.x === head.x && segment.y === head.y)) {
        setGameState('GAME_OVER');
        return prevSnake;
      }

      const newSnake = [head, ...prevSnake];

      // Eat food
      if (head.x === food.x && head.y === food.y) {
        const newScore = score + 10;
        setScore(newScore);
        if (newScore > highScore) {
          setHighScore(newScore);
          localStorage.setItem('snake_highscore', newScore.toString());
        }
        setFood(generateFood(newSnake));
      } else {
        newSnake.pop();
      }

      return newSnake;
    });
  }, [food, score, highScore, generateFood]);

  // Game loop
  useEffect(() => {
    if (gameState !== 'PLAYING' || isPaused) return;

    const interval = setInterval(moveSnake, gameSpeed);

    return () => clearInterval(interval);
  }, [gameState, isPaused, gameSpeed, moveSnake]);

  return (
    <div className="app-container">
      <div className="game-header">
        <h1>スネークゲーム</h1>
        <div className="score-board">
          <span>スコア: {score}</span>
          <span>ハイスコア: {highScore}</span>
        </div>
      </div>

      <div style={{ position: 'relative' }}>
        <GameBoard snake={snake} food={food} gridSize={GRID_SIZE} />

        {gameState === 'PLAYING' && isPaused && (
          <div className="overlay">
            <div className="modal">
              <h2>ポーズ中</h2>
              <p>スペースキーまたはボタンで再開</p>
              <button className="btn" onClick={togglePause}>
                再開する
              </button>
            </div>
          </div>
        )}

        {gameState === 'START' && (
          <div className="overlay">
            <div className="modal">
              <h2>スネークゲーム</h2>
              <p>矢印キーまたはボタンで操作してね！<br />スペースキーで一時停止</p>
              <button className="btn" onClick={startGame}>
                スタート
              </button>
            </div>
          </div>
        )}

        {gameState === 'GAME_OVER' && (
          <div className="overlay">
            <div className="modal">
              <h2>ゲームオーバー</h2>
              <p>スコア: {score}</p>
              <button className="btn" onClick={startGame}>
                リトライ
              </button>
            </div>
          </div>
        )}
      </div>

      <Controls
        onDirectionChange={handleDirectionChange}
        onRestart={startGame}
        gameState={gameState}
        onStart={startGame}
      />
    </div>
  );
}
